            aOrbiterG = (((aWandererG + RotL64(aScatter, 5U)) + RotL64(aCarry, 23U)) + 0x6349094A7307127EULL) + aTwistOrbiterAssignSaltD[((aIndex + 21U)) & S_SALT1];
