            aCross = (RotL64(aPoisonLaneC[((S_BLOCK1 - aIndex + 4106U)) & S_BLOCK1], 34U) ^ RotL64(aSoilLaneB[((S_BLOCK1 - aIndex + 2351U)) & S_BLOCK1], 43U));
