            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aCarry, 47U) + RotL64(aPrevious, 35U)) ^ (RotL64(aIngress, 4U) ^ RotL64(aCross, 23U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterC = ((aWandererJ + RotL64(aCross, 51U)) + 0x931F8ADC5C08952DULL) + aKeyRotateOrbiterAssignSaltE[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterB = ((aWandererH + RotL64(aScatter, 23U)) + RotL64(aCarry, 13U)) + 0x33695AE936DFA2E1ULL;
            aOrbiterE = (((aWandererA + RotL64(aPrevious, 58U)) + RotL64(aCarry, 29U)) + 0x4A942983B38EE9E1ULL) + aKeyRotateOrbiterAssignSaltB[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterH = (aWandererB + RotL64(aIngress, 35U)) + 0x65AC929B72EF2BA6ULL;
            aOrbiterK = (aWandererC + RotL64(aPrevious, 13U)) + 0xBEAE112DBD521B67ULL;
            aOrbiterJ = ((aWandererD + RotL64(aCross, 3U)) + RotL64(aCarry, 53U)) + 0xAF058BC36575916FULL;
            aOrbiterI = (aWandererK + RotL64(aScatter, 29U)) + 0x0F12E515A2DC5DE4ULL;
            //
            aOrbiterC = ((aOrbiterC + aOrbiterB) + 0x78B31FCFC605C8D4ULL) + aKeyRotateOrbiterUpdateSaltE[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterC) ^ 0x33A8C3573D6EDF65ULL) ^ aKeyRotateOrbiterUpdateSaltA[((aIndex + 25U)) & S_SALT1];
