            //
            aOrbiterH = (aOrbiterH + aOrbiterC) + 0xD23DC13433991015ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterH) ^ 0x5358BA72AE69D635ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x32F1E2F5E7CD9CF7ULL), 13U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0x93107B360EC4310CULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0x36BF86E08E36EBECULL;
            aOrbiterH = RotL64((aOrbiterH * 0x38C0BE34E13E96FBULL), 5U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterE) + 0x6D9723114DD8FC0EULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterI) ^ 0xDE6A7B50B0C2409CULL) ^ aKeyRotateOrbiterUpdateSaltD[(((31U - aIndex) + 10U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0xF0A499FB4E30E995ULL), 41U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterI) + 0x644E90F66F9BD4E0ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterK) ^ 0xBA6A1BEB07108733ULL) ^ aKeyRotateOrbiterUpdateSaltF[((aIndex + 28U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x468BF906F7EAB821ULL), 21U);
            //
            aIngress = RotL64(aOrbiterH, 29U) ^ aOrbiterI;
            aIngress = aIngress + (aOrbiterC ^ RotL64(aOrbiterB, 57U));
            aIngress = aIngress + (aOrbiterJ ^ RotL64(aOrbiterE, 3U));
