            aCross = (RotL64(aPoisonLaneA[((S_BLOCK1 - aIndex + 11299U)) & S_BLOCK1], 29U) ^ RotL64(aPoisonLaneD[((S_BLOCK1 - aIndex + 8810U)) & S_BLOCK1], 50U));
            aCross ^= (RotL64(aIceLaneA[((S_BLOCK1 - aIndex + 15895U)) & S_BLOCK1], 13U) ^ RotL64(aEarthLaneC[((aIndex + 10525U)) & S_BLOCK1], 21U));
            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aCross, 19U) + RotL64(aIngress, 37U)) ^ (RotL64(aCarry, 4U) + RotL64(aPrevious, 51U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterC = ((aWandererJ + RotL64(aIngress, 40U)) + RotL64(aCarry, 27U)) + 0xB0D451D8C189DDD7ULL;
            aOrbiterE = ((aWandererI + RotL64(aScatter, 57U)) + RotL64(aCarry, 51U)) + 0x48AE48A70C4BF5B6ULL;
            aOrbiterH = ((aWandererF + RotL64(aPrevious, 23U)) + RotL64(aCarry, 39U)) + 0x87CF60652B781936ULL;
            aOrbiterK = ((aWandererE + RotL64(aCross, 29U)) + 0xE359FDCBA344B114ULL) + aKeyRotateOrbiterAssignSaltA[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterB = (aWandererD + RotL64(aScatter, 3U)) + 0x50CA239E831E3181ULL;
            aOrbiterI = ((aWandererB + RotL64(aCross, 47U)) + 0xD0B8D8F652BCDBA1ULL) + aKeyRotateOrbiterAssignSaltD[((aIndex + 28U)) & S_SALT1];
            aOrbiterG = (aWandererG + RotL64(aIngress, 13U)) + 0xC9C4E5E8F7441A6CULL;
            //
            aOrbiterC = ((aOrbiterC + aOrbiterE) + 0xA20CF9CE39CBF12CULL) + aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 21U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterC) ^ 0x8EB972F6B556456BULL;
            aOrbiterH = RotL64((aOrbiterH * 0x9E28C7C0A36416D9ULL), 47U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterK) + 0xCB82C16763F0A76AULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterE) ^ 0x4BA6910E2381ADEDULL;
            aOrbiterB = RotL64((aOrbiterB * 0x9740A96871B8D1DDULL), 41U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterH) + 0xEBA844B3F655BA8FULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0xA10DE81A5B75AF05ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xC8CFBE2A17B80B01ULL), 27U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterI) + 0x680A130D7E222FD4ULL) + aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterB) ^ 0x2CD309AB0CBF5158ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x533B11C216CD07D7ULL), 19U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterG) + 0xC061F7AC91CB2294ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterI) ^ 0x275AE48DD1E8F1B7ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xA4E1944FCB7585E5ULL), 3U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterB) + 0xDBAA7189F331CB10ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterH) ^ 0x362EC87711890AA7ULL) ^ aKeyRotateOrbiterUpdateSaltA[(((31U - aIndex) + 26U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0xF5197AAF9A4AFC91ULL), 11U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterC) + 0x6FEC4DDF50CA1031ULL) + aKeyRotateOrbiterUpdateSaltF[((aIndex + 15U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterG) ^ 0x46ABCF2574D6E889ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xA566F307B73BA8CDULL), 57U);
            //
            aIngress = RotL64(aOrbiterI, 11U) ^ aOrbiterH;
            aIngress = aIngress + (RotL64(aOrbiterB, 27U) ^ aOrbiterK);
            aIngress = aIngress + (aOrbiterE ^ RotL64(aOrbiterG, 53U));
            aIngress = aIngress + RotL64(aOrbiterC, 41U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
