            aOrbiterB = (aWandererB + RotL64(aIngress, 21U)) + 0xB8E505D88C6EC840ULL;
            aOrbiterE = ((aWandererI + RotL64(aCross, 57U)) + 0xF9F5F09406F473D5ULL) + aKeyRotateOrbiterAssignSaltC[(((31U - aIndex) + 5U)) & S_SALT1];
