            aOrbiterI = ((aOrbiterI ^ aOrbiterB) ^ 0x0AB63036C94FB1B8ULL) ^ aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 13U)) & S_SALT1];
