            aOrbiterF = ((aWandererF + RotL64(aIngress, 14U)) + RotL64(aCarry, 51U)) + 0x58AD15D5B4A49182ULL;
            aOrbiterD = (aWandererH + RotL64(aScatter, 47U)) + 0x68C0F260686F443BULL;
