            //
            aIngress = (RotL64(aShadowLaneA[((aIndex + 4365U)) & S_BLOCK1], 41U) ^ RotL64(aShadowLaneB[((aIndex + 7908U)) & S_BLOCK1], 50U));
            aIngress ^= (RotL64(aPlasmaLaneD[((aIndex + 3419U)) & S_BLOCK1], 29U) ^ RotL64(aKeyRowReadB[(((2047U - aIndex) + 3492U)) & W_KEY1], 3U));
