            aIngress = aIngress + (aOrbiterJ ^ RotL64(aOrbiterA, 11U));
            aIngress = aIngress + (aOrbiterG ^ RotL64(aOrbiterF, 4U));
            aIngress = aIngress + (RotL64(aOrbiterE, 47U) ^ aOrbiterI);
