            aWandererJ = aWandererJ ^ ((RotL64(aPrevious, 43U) + aOrbiterD) + RotL64(aOrbiterC, 3U));
            aWandererD = aWandererD + (((RotL64(aIngress, 13U) + RotL64(aOrbiterD, 51U)) + aOrbiterH) + aKeyRotateWandererUpdateSaltB[((aIndex + 5U)) & S_SALT1]);
            aWandererC = aWandererC ^ ((RotL64(aCross, 57U) + aOrbiterK) + RotL64(aOrbiterC, 43U));
