            aWandererB = aWandererB ^ (((RotL64(aCross, 47U) + RotL64(aOrbiterK, 53U)) + aOrbiterD) + aKeyRotateWandererUpdateSaltD[((aIndex + 8U)) & S_SALT1]);
            aWandererK = aWandererK + ((RotL64(aIngress, 35U) + aOrbiterA) + RotL64(aOrbiterH, 57U));
