            aOrbiterH = (aOrbiterH + aOrbiterD) + 0xA7E39AC65CA23A84ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterH) ^ 0xDCA5503A7DD5AF01ULL) ^ aKeySpawnOrbiterUpdateSaltF[((aIndex + 7U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xB1F616DA5CB31D35ULL), 37U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterE) + 0x3EAC2A2CDDDE396CULL) + aKeySpawnOrbiterUpdateSaltD[((aIndex + 15U)) & S_SALT1];
