            aOrbiterI = RotL64((aOrbiterI * 0x7B2F9B87540EF585ULL), 27U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterI) + 0x2D2229721BC85D8FULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterG) ^ 0xF0D184243160862DULL) ^ aKeySpawnOrbiterUpdateSaltB[((aIndex + 27U)) & S_SALT1];
