            aScatter = (RotL64(aIngress, 19U) ^ RotL64(aCross, 34U)) + (RotL64(aCarry, 51U) ^ RotL64(aPrevious, 3U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterC = (aWandererE + RotL64(aIngress, 23U)) + 0x869BF992D7D15D90ULL;
            aOrbiterH = (aWandererI + RotL64(aScatter, 29U)) + 0x8B3AB533E73E458DULL;
