            aOrbiterF = ((aWandererJ + RotL64(aScatter, 51U)) + RotL64(aCarry, 13U)) + 0x07F23301210E1FC9ULL;
            aOrbiterK = (((aWandererH + RotL64(aPrevious, 47U)) + RotL64(aCarry, 27U)) + 0x26B6BB259610BF53ULL) + aKeySpawnOrbiterAssignSaltF[(((31U - aIndex) + 11U)) & S_SALT1];
