            aOrbiterG = ((aOrbiterG + aOrbiterC) + 0x148A5372D3738A5EULL) + aKeySpawnOrbiterUpdateSaltA[(((31U - aIndex) + 4U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterG) ^ 0x06C57B1AAF8E187CULL;
